import Anthropic from '@anthropic-ai/sdk';
import { readFileSync } from 'fs';
import { resolve } from 'path';
import 'dotenv/config';

const client = new Anthropic();

// Parse command-line arguments
const args = process.argv.slice(2);
if (args.length === 0) {
  console.error('Usage: node summarize.js <file> [--bullets]');
  console.error('Example: node summarize.js notes.txt --bullets');
  process.exit(1);
}

const filePath   = args[0];
const bulletsMode = args.includes('--bullets');

// Read the file
let fileContent;
try {
  fileContent = readFileSync(resolve(filePath), 'utf-8');
} catch (err) {
  console.error(`Error reading file: ${err.message}`);
  process.exit(1);
}

if (fileContent.trim().length === 0) {
  console.error('Error: File is empty.');
  process.exit(1);
}

// Build the prompt based on mode
const instruction = bulletsMode
  ? 'Summarize the following text as exactly 5 concise bullet points. Each bullet should capture one key idea. Start each bullet with a dash (-).'
  : 'Summarize the following text in 2-3 clear sentences. Be concise and capture the most important points.';

console.log(`Summarizing: ${filePath}`);
console.log(bulletsMode ? '(bullet point mode)' : '(paragraph mode)');
console.log('---');

// Stream the response
const stream = client.messages.stream({
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 400,
  system: 'You are a precise summarizer. Follow the format instructions exactly.',
  messages: [
    {
      role: 'user',
      content: `${instruction}\n\nText to summarize:\n\n${fileContent}`
    }
  ]
});

for await (const event of stream) {
  if (
    event.type === 'content_block_delta' &&
    event.delta.type === 'text_delta'
  ) {
    process.stdout.write(event.delta.text);
  }
}

process.stdout.write('\n');

const final = await stream.finalMessage();
console.log(`\n--- ${final.usage.input_tokens} in / ${final.usage.output_tokens} out tokens`);

按顺序完成每一步。每一步都会产出可运行的代码。

---

**第 1 步——项目搭建（2 分钟）**

在 VS Code 终端中：
```powershell
# You should already be in ai-course-projects/exercises
# Verify dependencies are installed
npm list @anthropic-ai/sdk dotenv
```
如果尚未安装：`npm install @anthropic-ai/sdk dotenv`

确认 `package.json` 中有 `"type": "module"`（来自第 11-5 课）。

确认 `.env` 文件存在，且包含 `ANTHROPIC_API_KEY=sk-ant-...`

---

**第 2 步——读取文件参数（5 分钟）**

创建 `exercises/summarize.js`，先只写参数解析部分：
```javascript
import { readFileSync } from 'fs';
import { resolve } from 'path';

const args = process.argv.slice(2);
if (args.length === 0) {
  console.error('Usage: node summarize.js <file>');
  process.exit(1);
}

const filePath = args[0];
const fileContent = readFileSync(resolve(filePath), 'utf-8');
console.log(`File length: ${fileContent.length} characters`);
console.log('First 200 chars:', fileContent.slice(0, 200));
```

在你的 README 上测试：
```powershell
node summarize.js ../README.md
```
你应该会看到字符数以及前 200 个字符。文件读取功能正常。

---

**第 3 步——添加 API 调用（10 分钟）**

把 Claude 调用添加到你的文件中：
```javascript
import Anthropic from '@anthropic-ai/sdk';
import { readFileSync } from 'fs';
import { resolve } from 'path';
import 'dotenv/config';

const client = new Anthropic();
const args = process.argv.slice(2);
if (args.length === 0) { console.error('Usage: node summarize.js <file>'); process.exit(1); }

const fileContent = readFileSync(resolve(args[0]), 'utf-8');

const message = await client.messages.create({
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 300,
  messages: [{
    role: 'user',
    content: `Summarize the following text in 2-3 sentences:\n\n${fileContent}`
  }]
});

console.log(message.content[0].text);
```

测试：`node summarize.js ../README.md`

你应该会看到 README 的摘要。核心功能已经跑通。

---

**第 4 步——添加流式传输（5 分钟）**

把 `messages.create` 调用替换成流式版本：
```javascript
const stream = client.messages.stream({
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 300,
  messages: [{
    role: 'user',
    content: `Summarize the following text in 2-3 sentences:\n\n${fileContent}`
  }]
});

for await (const event of stream) {
  if (event.type === 'content_block_delta' && event.delta.type === 'text_delta') {
    process.stdout.write(event.delta.text);
  }
}
process.stdout.write('\n');
```

再次测试：`node summarize.js ../README.md`

现在摘要会逐词流式呈现。

---

**第 5 步——添加 --bullets 标志（10 分钟）**

添加标志检查和条件提示词：
```javascript
const bulletsMode = process.argv.includes('--bullets');

const instruction = bulletsMode
  ? 'Summarize the following text as exactly 5 concise bullet points. Start each with a dash (-).'
  : 'Summarize the following text in 2-3 clear sentences.';

// Use instruction in the messages array content
```

测试两种模式：
```powershell
node summarize.js ../README.md
node summarize.js ../README.md --bullets
```

---

**第 6 步——添加错误处理并完善细节（10 分钟）**

用本课上面展示的完整最终代码替换你的文件。它增加了：
- 文件读取错误的 try/catch 处理
- 空文件检查
- 一行显示正在摘要的内容的状态行
- 结尾处的 token 用量

---

**第 7 步——在真实文件上测试（10 分钟）**

在几个真实文件上测试你的工具：
```powershell
# Summarize your notes
node summarize.js ../notes/my-ai-workflow.md
node summarize.js ../notes/my-ai-workflow.md --bullets

# Summarize your prompt library
node summarize.js ../prompts/my-prompt-library.md

# Try a longer file if you have one
node summarize.js some-article.txt
```

**需要留意的地方：**
- 这个工具适用于任何纯文本文件
- 要点模式会给出不同的结构
- token 用量展示了成本如何随文件长度变化
